def col_width(d):
    """Number of columns at distance d from center (d >= 2)"""
    period = 6  # Pattern 1,2,3,2,3,1 repeats
    mod = (d - 2) % period
    widths = [1, 2, 3, 2, 3, 1]
    return widths[min(mod, len(widths) - 1)]

def generate_diamond_pattern_v2(grid):
    """Transform: find 3x3 boxes and generate lower triangular diamonds below them"""
    h, w = len(grid), len(grid[0])

    boxes = []
    for r in range(h - 2):
        for c in range(w - 2):
            if (grid[r][c] == 3 and grid[r][c+1] == 3 and grid[r][c+2] == 3 and
                grid[r+1][c] == 3 and grid[r+1][c+2] == 3 and
                grid[r+2][c] == 3 and grid[r+2][c+1] == 3 and
                grid[r+1][c+1] != 3):
                boxes.append((r, c, r+2, c+2))

    result = [row[:] for row in grid]

    for box in boxes:
        top, left, bottom, right = box
        center_r, center_c = top + 1, left + 1

        for d in range(1, len(grid) - center_r):
            r = center_r + d
            if r >= len(grid):
                break

            # Skip d=1 (center row) - no 1s generated
            if d == 1:
                continue

            width = col_width(d)
            center = center_c

            # Columns are centered - need to calculate the range
            if width == 1:
                cols = [center]
            elif width == 2:
                cols = [center - 1, center + 1]
            elif width == 3:
                cols = [center - 1, center, center + 1]
            elif width == 4:
                cols = [center - 1, center, center + 1]  # Need to check this

            # Apply bounds
            cols = [c for c in cols if 0 <= c < w]

            for c in cols:
                result[r][c] = 1

    return result

